import { useMemo, useState } from 'react';
import './dashboard.css';

const teamMembers = [
    { name: 'Mark Chen', role: 'Product Manager', active: 12, overdue: 5, status: 'On Track' },
    { name: 'Emily Davis', role: 'UX Researcher', active: 10, overdue: 2, status: 'Under Pressure' },
    { name: 'John Smith', role: 'Frontend Developer', active: 15, overdue: 4, status: 'Sustained' },
    { name: 'Linda Johnson', role: 'Backend Developer', active: 9, overdue: 1, status: 'Overloaded' },
    { name: 'Michael Brown', role: 'QA Specialist', active: 20, overdue: 6, status: 'Balanced' },
];

function Dashboard({ userName, userRole, onLogout }) {
    const [activePage, setActivePage] = useState('Dashboard');
    const [search, setSearch] = useState('');
        const [tasks, setTasks] = useState([
        { id: 1, title: "Plan today's tasks", done: true },
        { id: 2, title: 'Complete project work', done: false },
        { id: 3, title: 'Review your progress', done: false },
    ]);
        const [newTask, setNewTask] = useState('');

        function toggleTask(id) {
            setTasks(tasks.map((task) => task.id === id ? { ...task, done: !task.done } : task));
        }

        function addTask(event) {
            event.preventDefault();
            if (!newTask.trim()) return;
            setTasks([...tasks, { id: Date.now(), title: newTask.trim(), done: false }]);
            setNewTask('');
        }

    const visibleMembers = useMemo(() => teamMembers.filter((member) => (
        member.name.toLowerCase().includes(search.toLowerCase())
        || member.role.toLowerCase().includes(search.toLowerCase())
    )), [search]);
    const completedTasks = tasks.filter((task) => task.done).length;
    const progress = tasks.length ? Math.round((completedTasks / tasks.length) * 100) : 0;
    const firstLetter = userName.charAt(0).toUpperCase();

    const navigation = [
        ['Dashboard', '▦'],
        ['Tasks', '✓'],
        ['Projects', '▱'],
        ['Analytics', '⌁'],
        ['Calendar', '□'],
        ['Team Members', '♙'],
        ['Reports', '▤'],
    ];

    return (
        <main className="dashboard-page">
            <div className="dashboard-shell">
                <aside className="dashboard-sidebar">
                    <div className="product-logo"><span className="logo-icon">◆</span> TaskFlow</div>
                    <p className="menu-label">Menu</p>
                    <nav aria-label="Main navigation">
                        {navigation.map(([label, icon]) => (
                            <button className={`nav-item ${activePage === label ? 'active' : ''}`} type="button" key={label} onClick={() => setActivePage(label)}>
                                <span>{icon}</span>{label}
                            </button>
                        ))}
                    </nav>
                    <p className="menu-label general-label">General</p>
                    <button className={`nav-item ${activePage === 'Settings' ? 'active' : ''}`} type="button" onClick={() => setActivePage('Settings')}><span>⚙</span>Settings</button>
                    <button className={`nav-item ${activePage === 'Help & Support' ? 'active' : ''}`} type="button" onClick={() => setActivePage('Help & Support')}><span>?</span>Help &amp; Support</button>
                    <button className="nav-item" type="button" onClick={onLogout}><span>↪</span>Logout</button>
                    <div className="upgrade-box"><strong>Upgrade to Pro</strong><p>Unlock advanced analytics and team productivity insights.</p><button type="button">Upgrade Now</button></div>
                </aside>

                <section className="dashboard-main">
                    <header className="dashboard-topbar">
                        <div>
                            <p className="dashboard-label">{activePage}</p>
                            <h1>Welcome back, {userName}! <span aria-hidden="true">👋</span></h1>
                            <p>Here&apos;s what&apos;s happening with your team today</p>
                        </div>
                        <div className="topbar-actions">
                            <label className="search-box"><span>⌕</span><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search here..." aria-label="Search team" /></label>
                            <button className="icon-button" type="button" aria-label="Notifications">♧</button>
                            <div className="account-box"><span className="user-avatar">{firstLetter}</span><span><strong>{userName}</strong><small>{userRole} account</small></span><span>⌄</span></div>
                        </div>
                    </header>

                    {activePage !== 'Dashboard' && (
                        <section className="working-page panel">
                            <p className="dashboard-label">Workspace</p>
                            <h2>{activePage}</h2>
                            <p>{activePage === 'Tasks' ? 'Create and update your tasks from here.' : `You are viewing the ${activePage.toLowerCase()} section.`}</p>
                            {activePage === 'Tasks' && (
                                <>
                                    <form className="quick-task-form" onSubmit={addTask}>
                                        <input value={newTask} onChange={(event) => setNewTask(event.target.value)} placeholder="Write a new task" aria-label="New task" />
                                        <button type="submit">Add Task</button>
                                    </form>
                                    <div className="quick-task-list">
                                        {tasks.map((task) => (
                                            <label className={task.done ? 'quick-task done' : 'quick-task'} key={task.id}>
                                                <input type="checkbox" checked={task.done} onChange={() => toggleTask(task.id)} />
                                                <span>{task.title}</span>
                                            </label>
                                        ))}
                                    </div>
                                </>
                            )}
                        </section>
                    )}

                    <section className="metric-grid" aria-label="Project summary">
                        <article className="metric-card blue"><strong>156</strong><span>Active Projects</span></article>
                        <article className="metric-card purple"><strong>82%</strong><span>Utilization Rate</span></article>
                        <article className="metric-card green"><strong>2.4 <small>Days</small></strong><span>Average Time</span></article>
                        <article className="metric-card pink"><strong>3</strong><span>At Risk Projects</span></article>
                    </section>

                    <section className="middle-grid">
                        <article className="panel status-panel">
                            <div className="panel-heading"><div><h2>Task Status Distribution</h2><p>Current progress across all tasks</p></div><button type="button" aria-label="More task status options">•••</button></div>
                            <div className="status-columns"><div className="status-stat blue-line"><span>● &nbsp;In Progress</span><strong>67%</strong><i /></div><div className="status-stat green-line"><span>● &nbsp;Completed</span><strong>24%</strong><i /></div><div className="status-stat yellow-line"><span>● &nbsp;Overdue</span><strong>9%</strong><i /></div></div>
                        </article>
                        <article className="panel priority-panel">
                            <div className="panel-heading"><div><h2>Task Priority</h2><p>Distribution by priority level</p></div><button type="button" aria-label="More priority options">•••</button></div>
                            <div className="donut-area"><div className="priority-donut"><span>100</span><small>Tasks</small></div></div>
                            <div className="legend"><span><i className="high-dot" />High Priority: 40</span><span><i className="medium-dot" />Medium Priority: 26</span><span><i className="low-dot" />Low Priority: 18</span></div>
                        </article>
                    </section>

                    <section className="bottom-grid">
                        <article className="panel activity-panel">
                            <div className="panel-heading"><div><h2>Team Activity</h2><p>Understand your team productivity and workload.</p></div><button type="button" aria-label="More team activity options">•••</button></div>
                            <div className="activity-number"><strong>{progress || 63}%</strong><span>+8% vs last week</span></div>
                            <div className="activity-chart" aria-label="Team activity by day"><div className="chart-bars">{[2, 4, 3, 5, 6, 6, 4].map((height, index) => <i style={{ '--bar-height': `${height * 13}px` }} key={index} />)}</div><div className="chart-days"><span>Sat</span><span>Sun</span><span>Mon</span><span>Tue</span><span>Wed</span><span>Thu</span><span>Fri</span></div></div>
                        </article>
                        <article className="panel workload-panel">
                            <div className="panel-heading"><div><h2>Team Workload</h2><p>Current workload across your team</p></div><button className="see-all" type="button">See All</button></div>
                            <div className="workload-table"><div className="table-head"><span>Name</span><span>Active work</span><span>Overdue</span><span>Status</span></div>{visibleMembers.map((member) => <div className="member-row" key={member.name}><span className="member-name"><i>{member.name.charAt(0)}</i><b>{member.name}<small>{member.role}</small></b></span><span>{member.active}</span><span>{member.overdue}</span><span><em className={member.status.toLowerCase().replaceAll(' ', '-')}>{member.status}</em></span></div>)}</div>
                        </article>
                    </section>
                </section>
            </div>
        </main>
    );
}

export default Dashboard;
